import { custom_form_creation } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    createPopup: Boolean
  },
  data() {
    return {
      formName: "",
      formDesc: "",
      loading: false
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
      this.$refs.form.reset();
    },
    validate_data() {
      if (this.$refs.form.validate()) {
        // this.create_form();
      }
    },
    async create_form() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(custom_form_creation, {
          input: {
            form_name: this.formName,
            form_description: this.formDesc,
            organization_id: data.organization.organization_id,
            user_email_id: data.user.user_email_id,
            action_type: this.actiontype == "CRM" ? "CRM_FLOWS" : "CUSTOM_FLOWS",
            product_id: this.actiontype == "CRM" ? this.$store.getters.Getproductitems.product_id : undefined
          }
        }));
        var response = JSON.parse(result.data.custom_form_creation);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
